"""Explicit individual reviews extending the Nordic archive; safe to rerun."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[2]
rows=json.loads((R/'data/nordic.json').read_text());cov=json.loads((R/'research/nordic-coverage.json').read_text())
for item in rows+cov['decisions']+cov['papers']:
 if item['country']=='Norway' and item['competition']=='Abel Competition':item['competition']='Abel Mathematical Competition'
new=[];reviews=[];papers=[]
def paper(country,year,problem,solution,date,competition='Skolornas matematiktävling',section='Final'):
 global ctx
 ctx=dict(country=country,competition=competition,year=year,section=section,sourceUrl=problem,solutionUrl=solution,sittingDate=date)
 papers.append(ctx|{'complete':True})
def q(num,rating,topic,statement,reason,subtopics,solution=None,notes=''):
 id=f"nordic-{ctx['country'].lower()}-{ctx['year']}-{num}"
 review={k:ctx[k] for k in ['country','competition','year','section']}|dict(id=id,number=str(num),difficulty=rating,ratingReason=reason,included=bool(statement) and 1<=rating<=10)
 reviews.append(review)
 if not review['included']:return
 new.append(ctx|dict(id=id,number=str(num),difficulty=rating,topic=topic,statement=statement,ratingReason=reason,tags=subtopics,subtopics=subtopics,reviewStatus='individually-assessed',solution=solution,solutionKind='original-exposition' if solution else 'source-link',solutionCredit='Independent mathematical exposition for Olympiad Atlas' if solution else 'Official competition solutions ('+('Norwegian' if ctx['country']=='Norway' else 'Swedish')+')',notes='English mathematical paraphrase of the official paper. '+notes))
def ex(num,rating,reason):q(num,rating,'',None,reason,[])
sw='https://www.mattetavling.se/s/'
